/* The portrait index enhances complete, source-preserving native disclosures. */
(()=>{'use strict';
const grid=document.querySelector('#yb-grid'),dialog=document.querySelector('.yb-reader');if(!grid||!dialog||typeof dialog.showModal!=='function')return;
const cards=[...grid.querySelectorAll('.yb-person')],byId=new Map(cards.map(e=>[e.querySelector('.yb-messages').id,e])),form=document.querySelector('.yb-filters'),search=document.querySelector('#yb-search'),sport=document.querySelector('#yb-sport'),alpha=document.querySelector('.yb-alpha'),counter=document.querySelector('#yb-count'),pagination=document.querySelector('.yb-pagination'),empty=document.querySelector('.yb-empty'),close=document.querySelector('#yb-close'),feedback=document.querySelector('#yb-feedback');
const entries=cards.map(card=>({card,id:card.querySelector('.yb-messages').id,name:card.dataset.name,sports:JSON.parse(card.dataset.sports),count:+card.dataset.count})),size=24;let current=null,opener=null,results=[],state={q:'',sport:'',letter:'',page:1},scrollYBefore=0,timer=0;
const normal=s=>s.normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase().trim();
const patchImages=within=>within.querySelectorAll('img').forEach(img=>{const missing=()=>{img.classList.add('is-missing');img.closest('.yb-photo')?.classList.add('has-missing');};img.addEventListener('error',missing);if(img.complete&&!img.naturalWidth)missing();});patchImages(grid);
function urlState(){const u=new URL(location.href),validSport=[...sport.options].some(o=>o.value===u.searchParams.get('sport'));state={q:u.searchParams.get('q')||'',sport:validSport?u.searchParams.get('sport')||'':'',letter:/^[A-Z]$/.test(u.searchParams.get('letter')||'')?u.searchParams.get('letter'):'',page:Math.max(1,parseInt(u.searchParams.get('page'))||1)};search.value=state.q;sport.value=state.sport;}
function write(mode='replace',hash=location.hash){const u=new URL(location.href);for(const k of ['q','sport','letter','page']){const v=state[k];if(v&&!(k==='page'&&v===1))u.searchParams.set(k,String(v));else u.searchParams.delete(k);}u.hash=hash;history[mode==='push'?'pushState':'replaceState']({},'',u);}
function render(){const pool=entries.filter(e=>normal(e.name).includes(normal(state.q))&&(!state.sport||e.sports.includes(state.sport)));results=pool.filter(e=>!state.letter||e.name[0].toUpperCase()===state.letter);const pages=Math.max(1,Math.ceil(results.length/size));state.page=Math.min(state.page,pages);const shown=new Set(results.slice((state.page-1)*size,state.page*size).map(e=>e.id));entries.forEach(e=>{e.card.hidden=!shown.has(e.id);e.card.open=false;});const messageCount=results.reduce((n,e)=>n+e.count,0);counter.textContent=`${results.length} name ${results.length===1?'entry':'entries'} · ${messageCount.toLocaleString('en-IN')} ${messageCount===1?'message':'messages'}`;empty.hidden=!!results.length;pagination.hidden=results.length<=size;document.querySelector('#yb-page').textContent=`${state.page} / ${pages}`;document.querySelector('#yb-prev').disabled=state.page===1;document.querySelector('#yb-next').disabled=state.page===pages;alpha.querySelectorAll('button').forEach(b=>{b.setAttribute('aria-pressed',String(b.dataset.letter===state.letter));b.disabled=!!b.dataset.letter&&!pool.some(e=>e.name[0].toUpperCase()===b.dataset.letter);});}
function restoreFocus(){if(opener?.isConnected&&!opener.closest('[hidden]')){const r=opener.getBoundingClientRect();if(r.bottom<0||r.top>innerHeight)opener.scrollIntoView({block:'center',behavior:'instant'});opener.focus({preventScroll:true});}else search.focus({preventScroll:true});}
function closeReader(update=true){if(!dialog.open)return;dialog.close();document.body.style.overflow='';current=null;if(update)write('replace','');restoreFocus();}
function openReader(id,{push=false,focus=true}={}){const card=byId.get(id);if(!card)return;const resultIndex=results.findIndex(e=>e.id===id);if(resultIndex>=0&&state.page!==Math.floor(resultIndex/size)+1){state.page=Math.floor(resultIndex/size)+1;render();}current=id;card.open=false;const summary=card.querySelector('summary'),left=dialog.querySelector('.yb-reader-person'),right=dialog.querySelector('.yb-messages');left.replaceChildren();const photo=summary.querySelector('.yb-photo').cloneNode(true);photo.querySelectorAll('img').forEach(i=>i.removeAttribute('loading'));const heading=document.createElement('h2');heading.id='reader-title';heading.textContent=card.dataset.name;const categories=document.createElement('p');categories.textContent=JSON.parse(card.dataset.sports).join(' · ');const pdf=document.createElement('a');pdf.className='yb-link';pdf.href=document.querySelector('#publication a[download]').href;pdf.target='_blank';pdf.rel='noopener';pdf.textContent='Original publication ↗';left.append(photo,heading,categories,pdf);right.replaceChildren(...[...card.querySelector('.yb-messages').children].map(n=>{const c=n.cloneNode(true);c.removeAttribute('id');return c;}));patchImages(left);const n=+card.dataset.count;document.querySelector('#reader-count').textContent=`${n} ${n===1?'message':'messages'} for ${card.dataset.name.split(' ')[0]}.`;document.querySelector('#yb-copy-link').textContent='Copy link ↗';const i=results.findIndex(e=>e.id===id);document.querySelector('#yb-reader-prev').disabled=i<=0;document.querySelector('#yb-reader-next').disabled=i<0||i>=results.length-1;if(push)write('push','#'+id);if(!dialog.open){scrollYBefore=scrollY;document.body.style.overflow='hidden';dialog.showModal();}dialog.scrollTop=0;if(focus)close.focus({preventScroll:true});}
function hashSync(){let id='';try{id=decodeURIComponent(location.hash.slice(1));}catch{}if(byId.has(id)){const index=results.findIndex(e=>e.id===id);if(index>=0){state.page=Math.floor(index/size)+1;render();}opener=byId.get(id).querySelector('summary');openReader(id);}else closeReader(false);}
function sync(){urlState();render();hashSync();}
function reset(){clearTimeout(timer);state={q:'',sport:'',letter:'',page:1};search.value='';sport.value='';render();write('push','');}
try{document.documentElement.classList.add('yb-enhanced');document.querySelector('#yb-tools').hidden=false;alpha.hidden=false;urlState();render();hashSync();}catch(error){document.documentElement.classList.remove('yb-enhanced');document.querySelector('#yb-tools').hidden=true;alpha.hidden=true;cards.forEach(e=>e.hidden=false);console.error('Yearbook index fallback',error);return;}
cards.forEach(card=>card.querySelector('summary').addEventListener('click',event=>{event.preventDefault();opener=event.currentTarget;openReader(card.querySelector('.yb-messages').id,{push:true});}));
search.addEventListener('input',()=>{clearTimeout(timer);timer=setTimeout(()=>{state.q=search.value;state.letter='';state.page=1;render();write('replace','');},120);});sport.addEventListener('change',()=>{clearTimeout(timer);state.q=search.value;state.sport=sport.value;state.page=1;state.letter='';render();write('push','');});form.addEventListener('submit',e=>e.preventDefault());form.addEventListener('reset',e=>{e.preventDefault();reset();});document.querySelector('[data-clear]').addEventListener('click',reset);
alpha.addEventListener('click',e=>{const b=e.target.closest('[data-letter]');if(!b)return;clearTimeout(timer);state.q=search.value;state.letter=b.dataset.letter;state.page=1;render();write('push','');});
for(const [id,delta] of [['#yb-prev',-1],['#yb-next',1]])document.querySelector(id).addEventListener('click',()=>{state.page+=delta;render();write('push','');document.querySelector('.yb-index-meta').scrollIntoView({block:'start',behavior:'instant'});});
close.addEventListener('click',()=>closeReader());dialog.addEventListener('cancel',e=>{e.preventDefault();closeReader();});
for(const [id,delta] of [['#yb-reader-prev',-1],['#yb-reader-next',1]])document.querySelector(id).addEventListener('click',()=>{const i=results.findIndex(e=>e.id===current),next=results[i+delta];if(next){opener=next.card.querySelector('summary');openReader(next.id,{push:true});}});
document.querySelector('#yb-copy-link').addEventListener('click',async e=>{const button=e.currentTarget;try{await navigator.clipboard.writeText(location.href);button.textContent='Link copied ✓';feedback.textContent='Link copied to this name entry.';}catch{button.textContent='Link is in address bar';feedback.textContent='Copy the link from your browser address bar.';}});
addEventListener('popstate',sync);addEventListener('hashchange',hashSync);
})();
